import {escapeHtml as e,uiIcons} from './ui.js';
let opened=false;
let practice='';
const steps=[
 {title:'Wie möchtest du VConnect nutzen?',label:'Deine Rolle',icon:'✧',body:'Als VTuber kannst du Collab-Partner finden. Als Zuschauer entdeckst du neue Streams. Deine Rolle lässt sich später im Profil ändern.',target:'#account',action:'Rolle auswählen'},
 {title:'Ein Profil mit Wiedererkennungswert.',label:'Dein Look',icon:'✦',body:'Lade unter „Design“ dein Profilbild und Banner hoch oder wähle Farben und Symbole. Passe den Ausschnitt an. Die Live-Vorschau zeigt das Ergebnis vor dem Speichern.',target:'[data-page="Profil"]',action:'Profil gestalten'},
 {title:'Hilf anderen, dich zu entdecken.',label:'Interessen & Links',icon:'◎',body:'Trage Games und Interessen mit Kommas getrennt ein. Ergänze Sprachen, Stream-Zeiten und deine Kanäle. Diese Angaben helfen auch bei deinen Empfehlungen.',target:'[data-page="Profil"]',action:'Interessen ergänzen'},
 {title:'Links weiter. Rechts merken.',label:'Swipen lernen',icon:'♡',body:'Ziehe eine Karte nach rechts, um das Profil zu merken, oder nach links, um es zu überspringen. Pfeiltasten und Buttons funktionieren ebenfalls. Rückgängig nimmt die letzte Entscheidung zurück.',target:'[data-page="Entdecken"]',action:'VTuber entdecken'},
 {title:'Aus einem Swipe wird eine Connection.',label:'Deine Connections',icon:'◇',body:'Gemerkte Profile stehen unter Connections. Öffne ein Profil, lies die Collab-Formate und besuche die verlinkten Kanäle. Merken ist einseitig und bedeutet noch kein gegenseitiges Match.',target:'[data-page="Connections"]',action:'Connections ansehen'},
 {title:'Teile, was bei dir passiert.',label:'Dein erster Beitrag',icon:'↗',body:'Erstelle einen Gedanken, eine Collab-Suche oder eine Stream-Ankündigung. In Art teilst du Bilder deiner Arbeiten, in Design Projekte und Codeblöcke. Wähle den Kanal im Editor. Beiträge sind öffentlich auf VConnect sichtbar.',target:'#write',action:'Beitragseditor öffnen'},
 {title:'Bereit für deine nächsten Connections.',label:'Alles bereit',icon:'✦',body:'Likes zeigen, was dir gefällt. Lesezeichen speichern Beiträge für später. „Für dich“ berücksichtigt deine Interessen und Connections; „Neueste“ sortiert ausschließlich nach Zeit. Du kannst diese Tour jederzeit wieder starten.',target:'[data-page="Lesezeichen"]',action:'Lesezeichen ansehen'}
];
export function tutorialCard(progress){const done=progress?.status==='completed',step=progress?.step??0;return `<section class="tutorial-launcher right-card"><div class="tutorial-launcher-icon">✧</div><span class="eyebrow">VCONNECT KENNENLERNEN</span><h3>${done?'Deine Tour. Jederzeit wieder.':'Ein guter Start für deine Connections.'}</h3><p>${done?'Alle Funktionen Schritt für Schritt entdecken.':`${step} von 7 Stationen · In deinem Tempo`}</p><div class="tour-mini-progress">${steps.map((_,i)=>`<span class="${done||i<step?'done':''}"></span>`).join('')}</div><button id="startTour" class="secondary">${done?'Tour erneut starten':step?'Tour fortsetzen':'Tour starten'} ${uiIcons.arrow}</button></section>`}
export function startTutorial(){opened=true;practice=''}
export function closeTutorial(){opened=false}
export function mountTutorial({state,go,edit,compose,save,updateProfile}){
 document.querySelector('#tutorialPanel')?.remove();document.querySelectorAll('.tour-focus').forEach(el=>el.classList.remove('tour-focus'));
 if(!opened||!state.active||['/login','/register'].includes(location.pathname))return;
 const step=Math.min(6,state.onboarding?.step??0),info=steps[step],panel=document.createElement('aside');panel.id='tutorialPanel';panel.className='tutorial-panel';panel.setAttribute('role','region');panel.setAttribute('aria-label','VConnect Tutorial');
 panel.innerHTML=`<div class="tutorial-top"><span>DEINE VCONNECT-TOUR</span><button id="tourPause" class="icon-control" aria-label="Tutorial pausieren">${uiIcons.close}</button></div><div class="tour-progress" aria-label="Schritt ${step+1} von 7">${steps.map((_,i)=>`<span class="${i<=step?'done':''}"></span>`).join('')}</div><div class="tour-step-label">${info.icon} ${e(info.label)} <span>0${step+1} / 07</span></div><h2 tabindex="-1">${info.title}</h2><p>${info.body}</p>${step===0?`<div class="tour-roles"><button data-tour-role="VTuber"><strong>✧ Ich bin VTuber</strong><small>Collabs & Community</small></button><button data-tour-role="Zuschauer"><strong>♡ Ich schaue Streams</strong><small>Entdecken & vernetzen</small></button></div>`:step===3?`<div class="swipe-practice"><div id="practiceCard" class="practice-card"><span>✦</span><strong>Dein Übungsswipe</strong><small>Übung ohne Änderung deiner Connections</small></div><div><button id="practiceSkip" aria-label="Übung: überspringen">×</button><span id="practiceResult" role="status">${practice||'Probiere die Buttons aus'}</span><button id="practiceLike" aria-label="Übung: merken">♡</button></div></div>`:''}<button id="tourAction" class="tour-action">${info.action} ${uiIcons.arrow}</button><div class="tour-footer"><button id="tourBack" ${step===0?'disabled':''}>← Zurück</button><button id="tourNext" class="primary">${step===6?'Tour abschließen':'Weiter'} ${step===6?'✓':'→'}</button></div><div id="tourError" role="alert"></div>`;
 document.body.append(panel);document.querySelector(info.target)?.classList.add('tour-focus');
 let pending=false;
 async function move(next,status='active'){if(pending)return;pending=true;panel.setAttribute('aria-busy','true');try{if(status!=='active')opened=false;await save({step:next,status});}catch(err){opened=true;panel.querySelector('#tourError').textContent=err.message}finally{pending=false;panel.setAttribute('aria-busy','false')}}
 panel.querySelector('#tourPause').onclick=()=>move(step,'paused');panel.querySelector('#tourBack').onclick=()=>move(Math.max(0,step-1));panel.querySelector('#tourNext').onclick=()=>move(Math.min(6,step+1),step===6?'completed':'active');
 panel.querySelector('#tourAction').onclick=()=>{if(step===0){panel.querySelector('[data-tour-role]')?.focus()}else if([1,2].includes(step))edit(step===1?'design':'identity');else if(step===3)go('Entdecken');else if(step===4)go('Connections');else if(step===5)compose();else go('Lesezeichen')};
 panel.querySelectorAll('[data-tour-role]').forEach(button=>button.onclick=async()=>{if(pending)return;pending=true;try{await updateProfile(button.dataset.tourRole);pending=false;await move(1)}catch(err){panel.querySelector('#tourError').textContent=err.message;pending=false}});
 for(const [id,message,cls] of [['practiceLike','Nach rechts: Profil merken.','practice-right'],['practiceSkip','Nach links: Profil überspringen.','practice-left']]){const button=panel.querySelector('#'+id);if(button)button.onclick=()=>{practice=message;panel.querySelector('#practiceResult').textContent=message;const card=panel.querySelector('#practiceCard');card.classList.remove('practice-left','practice-right');void card.offsetWidth;card.classList.add(cls)}}
}
